export default class HeaderSearch extends HTMLElement {
    constructor() {
        super();

        this.innerDOM = document.createElement("div")
        this.innerDOM.classList.add("header-search-wrapper")
        if(this.getAttribute("data-class")) {
          this.innerDOM.classList.add(this.getAttribute("data-class"))
        }
        this.innerDOM.appendChild(template.content.cloneNode(true))

        this.innerDOM.querySelector(".search .search__input").setAttribute("placeholder", this.getAttribute("data-placeholder-text"))


        this.cachedResults = {};
        this.input = this.innerDOM.querySelector('input[type="text"]');
        this.recommendList = this.innerDOM.querySelector('.recommend-search-list');
        this.predictiveSearchResults = this.innerDOM.querySelector('[data-header-search]');
        this.isOpen = false;

        this.setupEventListeners();

        let shadow = this.attachShadow({
          mode: 'open'
        })
        shadow.appendChild(this.innerDOM)

        this.renderRecommendList();

        const _self = this
        this.innerDOM.querySelector(".search-modal__close-button").addEventListener("click", function() {
            document.querySelector(".header-search__private").classList.add('fade-out');
            document.querySelector(".header-search__private").querySelector('.modal-content').classList.add('slide-out');
            setTimeout(function () {
              document.querySelector(".header-search__private").style.display = 'none';
              document.querySelector(".header-search__private").classList.remove('fade-out');
              document.querySelector(".header-search__private").querySelector('.modal-content').classList.remove('slide-out');
              // 恢复页面滚动
              resetContentWidth()
            }, 300);
            _self.close()
        })

        // 推荐搜索词点击事件
        this.innerDOM.querySelectorAll(".recommend-search-list a.predictive-search__item").forEach((item) => {
            item.addEventListener("click", function() {
                _self.input.value = this.text;
                _self.input.focus();
            })
        })
    }

    // 监听打开 - [hd-open] 变化即打开
    static get observedAttributes() {
      return ['hd-open'];
    }
    attributeChangedCallback(name, oldValue, newValue) {
      if (name === 'hd-open') {
        this.open()
      }
    }

    setupEventListeners() {
        const form = this.innerDOM.querySelector('form.search');
        form.addEventListener('submit', this.onFormSubmit.bind(this));

        this.input.addEventListener('input', debounce((event) => {
            this.onChange(event);
        }, 300).bind(this));
        this.input.addEventListener('focus', this.onFocus.bind(this));
        this.addEventListener('focusout', this.onFocusOut.bind(this));
        this.addEventListener('keyup', this.onKeyup.bind(this));
        this.addEventListener('keydown', this.onKeydown.bind(this));
    }

    getQuery() {
        return this.input.value.trim();
    }

    onChange() {
        const searchTerm = this.getQuery();

        // 显示或隐藏推荐搜索词列表
        this.toggleRecommendList(searchTerm.length === 0);

        this.getSearchResults(searchTerm);
    }

    onFormSubmit(event) {
        // if (!this.getQuery().length || this.innerDOM.querySelector('[aria-selected="true"] a')) event.preventDefault();
        if (this.innerDOM.querySelector('[aria-selected="true"] a')) event.preventDefault();
    }

    onFocus() {
        const searchTerm = this.getQuery();

        // 显示或隐藏推荐搜索词列表
        this.toggleRecommendList(searchTerm.length === 0);

        if (!searchTerm.length) return;

        if (this.getAttribute('results') === 'true') {
            this.open();
        } else {
            this.getSearchResults(searchTerm);
        }
    }

    onFocusOut() {
        setTimeout(() => {
            if (!this.contains(document.activeElement)) this.close();
        })
    }

    onKeyup(event) {
        if (!this.getQuery().length) this.close(true);
        event.preventDefault();

        switch (event.code) {
            case 'ArrowUp':
                this.switchOption('up')
                break;
            case 'ArrowDown':
                this.switchOption('down');
                break;
            case 'Enter':
                this.selectOption();
                break;
        }
    }

    onKeydown(event) {
        // Prevent the cursor from moving in the input when using the up and down arrow keys
        if (
            event.code === 'ArrowUp' ||
            event.code === 'ArrowDown'
        ) {
            event.preventDefault();
        }
    }

    switchOption(direction) {
        if (!this.getAttribute('open')) return;

        const moveUp = direction === 'up';
        const selectedElement = this.innerDOM.querySelector('[aria-selected="true"]');
        const allElements = this.innerDOM.querySelectorAll('li');
        let activeElement = this.innerDOM.querySelector('li');

        if (moveUp && !selectedElement) return;

        this.statusElement.textContent = '';

        if (!moveUp && selectedElement) {
            activeElement = selectedElement.nextElementSibling || allElements[0];
        } else if (moveUp) {
            activeElement = selectedElement.previousElementSibling || allElements[allElements.length - 1];
        }

        if (activeElement === selectedElement) return;

        activeElement.setAttribute('aria-selected', true);
        if (selectedElement) selectedElement.setAttribute('aria-selected', false);

        this.setLiveRegionText(activeElement.textContent);
        this.input.setAttribute('aria-activedescendant', activeElement.id);
    }

    selectOption() {
        const selectedProduct = this.innerDOM.querySelector('[aria-selected="true"] a, [aria-selected="true"] button');

        if (selectedProduct) selectedProduct.click();
    }

    getSearchResults(searchTerm) {
        const queryKey = searchTerm.replace(" ", "-").toLowerCase();
        this.setLiveRegionLoadingState();

        if (this.cachedResults[queryKey]) {
            this.renderSearchResults(this.cachedResults[queryKey]);
            return;
        }
        fetch(`${routes.predictive_search_url}?q=${encodeURIComponent(searchTerm)}&${encodeURIComponent('resources[type]')}=${window.pageInfo.search_query || "product,article"}&${encodeURIComponent('resources[limit]')}=4&section_id=predictive-search`)
            .then((response) => {
                if (!response.ok) {
                    var error = new Error(response.status);
                    this.close(false);
                    // fix no support lang
                    throw error;
                }

                return response.text();
            })
            .then((text) => {
              const doc = new DOMParser().parseFromString(text, 'text/html');
              const searchSection = doc.querySelector('#shopify-section-predictive-search');
              if (searchSection) {
                const shopIds = ['55005249633', '79611232554', '60738666677', '9709262'] // Demo Uat Ca Us
                if (shopIds.includes(window.shopId)) {
                  const productsContainer = searchSection.querySelector(
                    'ul#predictive-search-results-list[aria-labelledby="predictive-search-products"]'
                  );

                  if (productsContainer) {
                    this.sortProductList(productsContainer);
                  }
                }
                const resultsMarkup = searchSection.innerHTML;
                this.cachedResults[queryKey] = resultsMarkup;
                this.renderSearchResults(resultsMarkup);
              }
            })
            .catch((error) => {
                this.close(false);
                throw error;
            });
    }

    sortProductList(ul) {
      if (!ul) return;

      const items = Array.from(ul.querySelectorAll('li')).map((el, idx) => ({
        el,
        text: el.textContent.toLowerCase().replace(/\s+/g, ''),
        index: idx
      }));

      const getRank = (text) => {
        if (text.includes('refurbished')) return 2;
        if (text.includes('add-on')) return 3;
        if (text.includes('series')) return 4;
        return 1; // 普通商品优先
      };

      items.sort((a, b) => {
        const rankDiff = getRank(a.text) - getRank(b.text);
        return rankDiff !== 0 ? rankDiff : a.index - b.index;
      });

      const fragment = document.createDocumentFragment();
      items.forEach(item => {
        fragment.appendChild(item.el);
      });

      ul.innerHTML = '';
      ul.appendChild(fragment);

      return ul;
    }

    setLiveRegionLoadingState() {
        this.statusElement = this.statusElement || this.innerDOM.querySelector('.header-search-status');
        this.loadingText = this.loadingText || this.getAttribute('data-loading-text');

        this.setLiveRegionText(this.loadingText);
        this.setAttribute('loading', true);
    }

    setLiveRegionText(statusText) {
        this.statusElement.setAttribute('aria-hidden', 'false');
        this.statusElement.textContent = statusText;

        setTimeout(() => {
            this.statusElement.setAttribute('aria-hidden', 'true');
        }, 1000);
    }

    renderSearchResults(resultsMarkup) {
        this.predictiveSearchResults.innerHTML = resultsMarkup;



        this.setAttribute('results', true);

        this.setLiveRegionResults();
        this.open();
    }

    setLiveRegionResults() {
      this.innerDOM.removeAttribute('loading');
        this.setLiveRegionText(this.innerDOM.querySelector('[data-predictive-search-live-region-count-value]').textContent);
    }

    getResultsMaxHeight() {
        // this.resultsMaxHeight = window.innerHeight - document.getElementById('shopify-section-header').getBoundingClientRect().bottom;
        this.resultsMaxHeight = window.innerHeight * 0.7
        return this.resultsMaxHeight;
    }

    open() {
        this.predictiveSearchResults.style.maxHeight = this.resultsMaxHeight || `${this.getResultsMaxHeight()}px`;
        this.innerDOM.setAttribute('open', true);
        this.input.setAttribute('aria-expanded', true);
        this.isOpen = true;
        setTimeout(() => {
            this.input.focus()
        }, 10);
    }

    close(clearSearchTerm = true) {
        if (clearSearchTerm) {
            this.input.value = '';
            this.removeAttribute('results');
        }

        const selected = this.innerDOM.querySelector('[aria-selected="true"]');

        if (selected) selected.setAttribute('aria-selected', false);

        this.input.setAttribute('aria-activedescendant', '');
        this.innerDOM.removeAttribute('open');
        this.input.setAttribute('aria-expanded', false);
        this.resultsMaxHeight = false
        this.predictiveSearchResults.removeAttribute('style');

        this.isOpen = false;
        this.innerDOM.removeAttribute('loading');
    }

    /**
     * 渲染推荐关键词
     */
    renderRecommendList() {
    if (!window.websiteRecommendSearch) { return; }

    let listHtml = '';
    window.websiteRecommendSearch.list.forEach((item) => {
      listHtml += `<li class="predictive-search__list-item"><a class="predictive-search__item" href="${item.link}">${item.title}</a></li>`;
    })

    const recommendListHtml = `
      <h2 class="predictive-search__heading">${window.websiteRecommendSearch.title}</h2>
      <ul class="predictive-search__results-list">${listHtml}</ul>`;

    this.recommendList.innerHTML = recommendListHtml;
    }

    /**
     * 显示或隐藏推荐词列表
     * @param flag true/false
     */
    toggleRecommendList(flag) {
        if (!window.websiteRecommendSearch) { return; }
        if (flag) {
            this.recommendList.style.display = 'block';
        } else {
            this.recommendList.style.display = 'none';
        }
    }
}
